def find_number_combinations():
    import itertools

    def _valid(num):
        s = str(num)
        if '0' in s:
            return False
        if len(set(s)) != len(s):
            return False
        # all digits must be 1-9
        for ch in s:
            if ch not in '123456789':
                return False
        return True

    results = []
    digits = '123456789'
    for length in range(1, 10):
        for perm in itertools.permutations(digits, length):
            first = int(''.join(perm))
            second = first * 2
            third = first * 3
            if _valid(second) and _valid(third):
                results.append((first, second, third))

    results.sort(key=lambda x: x[0])
    return results

