def sum_of_factorials_optimized(n: int) -> int:
    """Compute cumulative sum of factorials 1! up to n!."""
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 1 or n > 50:
        raise ValueError("n must be in range 1 to 50 inclusive")
    factorial = 1
    total = 0
    for i in range(1, n + 1):
        factorial *= i
        total += factorial
    return total

def cantor_numbering(N: int) -> str:
    """Return the fraction at position N in the Cantor table."""
    if not isinstance(N, int) or N <= 0:
        raise ValueError("N must be a positive integer")
    # Find the diagonal `d` that contains the N-th term.
    low, high = 1, 1
    while high * (high + 1) // 2 < N:
        high <<= 1
    while low < high:
        mid = (low + high) // 2
        if mid * (mid + 1) // 2 >= N:
            high = mid
        else:
            low = mid + 1
    d = low
    # Number of terms before this diagonal
    prev = (d - 1) * d // 2
    k = N - prev  # position within the diagonal, 1-indexed
    if d % 2 == 0:
        numerator = k
        denominator = d - k + 1
    else:
        numerator = d - k + 1
        denominator = k
    return f"{numerator}/{denominator}"

def cantor_numbering(N: int) -> str:
    if N <= 0:
        raise ValueError("N must be a positive integer")
    p, q = 1, 1
    # Build the binary representation of N and drop the leading '1'
    bits = []
    n = N
    while n > 1:
        bits.append(n & 1)
        n >>= 1
    # Iterate over the bits in the original order (after the leading '1')
    for bit in reversed(bits):
        if bit == 0:
            p, q = p, p + q   # move Left: (p, p+q)
        else:
            p, q = p + q, q   # move Right: (p+q, q)
    return f"{p}/{q}"

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product that can be obtained by inserting K multiplication signs into the number string `num_str`.
    Each partition is interpreted as an integer (leading zeros are ignored by int conversion). If K is invalid (negative or greater than N-1),
    the function returns 0. The function works for non-empty strings of decimal digits.
    """
    # Sanitize input length
    num_str = num_str.strip()
    if not num_str:
        return 0
    N_actual = len(num_str)
    if N != N_actual:
        N = N_actual

    # Validate K
    if K < 0 or K > N - 1:
        return 0
    if K == 0:
        try:
            return int(num_str)
        except ValueError:
            return 0

    # Precompute substring integer values
    val = [[0] * (N + 1) for _ in range(N)]
    for i in range(N):
        for j in range(i + 1, N + 1):
            # Convert substring num_str[i:j] to integer
            try:
                val[i][j] = int(num_str[i:j])
            except ValueError:
                val[i][j] = 0

    # DP table: dp[i][k] = max product using first i characters with k multiplication signs
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    for i in range(1, N + 1):
        dp[i][0] = val[0][i]

    for i in range(1, N + 1):
        max_k_for_i = min(K, i - 1)  # need at least k+1 parts to split i characters
        for k in range(1, max_k_for_i + 1):
            best = 0
            # t is the end position of the previous part
            for t in range(k, i):
                left = dp[t][k - 1]
                current = left * val[t][i]
                if current > best:
                    best = current
            dp[i][k] = best

    return dp[N][K] if K <= N - 1 else 0

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product obtainable by inserting K multiplication
    signs into the numeric string `num_str` of length N.
    """
    # Validate input
    if N != len(num_str):
        N = len(num_str)
    if K < 0 or K > N - 1:
        return 0

    # Precompute integer values of all substrings
    substr = [[0] * (N + 1) for _ in range(N)]
    for i in range(N):
        num = 0
        for j in range(i, N):
            num = num * 10 + (ord(num_str[j]) - 48)  # faster int conversion
            substr[i][j + 1] = num

    # DP table: dp[pos][k] = best product using first `pos` characters with `k` multiplications
    dp = [[-1] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1  # base case: product of zero numbers

    for pos in range(1, N + 1):
        for k in range(0, K + 1):
            best = -1
            # Explore the last partition ending at `pos`
            for prev in range(pos):
                seg_val = substr[prev][pos]
                if k == 0:
                    best = seg_val if seg_val > best else best
                else:
                    prev_val = dp[prev][k - 1]
                    if prev_val != -1:
                        prod = prev_val * seg_val
                        best = prod if prod > best else best
            dp[pos][k] = best

    return dp[N][K] if dp[N][K] != -1 else 0

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    if len(coeffs) != n + 1:
        raise ValueError("Length of coeffs must be n + 1")

    parts = []

    for idx, coeff in enumerate(coeffs):
        if coeff == 0:
            continue

        degree = n - idx
        abs_coeff = abs(coeff)

        # Determine sign
        sign = '-' if coeff < 0 else '+'
        is_first = not parts

        # Coefficient string
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = '' if abs_coeff == 1 else str(abs_coeff)

        # Variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        term = coeff_str + var_str

        if is_first:
            if sign == '-':
                parts.append('-' + term)
            else:
                parts.append(term)
        else:
            parts.append(sign + term)

    return ''.join(parts) if parts else '0'

