def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that
    gcd(P, Q) = x0 and lcm(P, Q) = y0.
    """
    # Validate inputs: must be positive integers
    if x0 <= 0 or y0 <= 0:
        return 0

    # If y0 is not a multiple of x0, no such pairs exist
    if y0 % x0 != 0:
        return 0

    # Helper function: gcd via Euclidean algorithm
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    K = y0 // x0  # product of the reduced factors
    count = 0
    limit = int(K ** 0.5) + 1
    for a in range(1, limit):
        if K % a == 0:
            b = K // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

