    if not isinstance(tao_reach, (int, float)):
        return 0

    try:
        effective_reach = tao_reach + 30
    except Exception:
        return 0

    count = 0
    for height in apple_heights:
        try:
            if isinstance(height, (int, float)) and height <= effective_reach:
                count += 1
        except Exception:
            continue

    return count

def remaining_trees_after_clearing(l, areas):
    # Handle trivial cases
    if l <= 0 or not areas:
        return max(l, 0)
    # Convert each area to a [start, end) interval clipped to [0, l]
    intervals = []
    for start, end in areas:
        # clip bounds
        s = max(0, min(start, l))
        e = max(0, min(end, l))
        if s < e:
            intervals.append((s, e))
    if not intervals:
        return l
    # Merge overlapping intervals
    intervals.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = intervals[0]
    for s, e in intervals[1:]:
        if s <= cur_end:
            cur_end = max(cur_end, e)
        else:
            merged.append((cur_start, cur_end))
            cur_start, cur_end = s, e
    merged.append((cur_start, cur_end))
    # Sum lengths of merged intervals
    removed = sum(e - s for s, e in merged)
    remaining = l - removed
    return remaining if remaining > 0 else 0

def minimum_students_to_leave(heights):
    """
    Return the minimum number of students that need to leave so that the remaining heights
    form a strictly increasing then strictly decreasing sequence (mountain shape).
    This is equivalent to removing the fewest elements to obtain the longest
    bitonic subsequence.

    :param heights: List[int] – list of student heights.
    :return: int – minimum number of students to remove.
    """
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    for h in heights:
        if not isinstance(h, int):
            raise TypeError("all elements of heights must be integers")

    n = len(heights)
    if n <= 1:
        return 0

    # LIS[i]: longest increasing subsequence ending at index i
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # LDS[i]: longest decreasing subsequence starting at index i
    lds = [1] * n
    for i in reversed(range(n)):
        for j in range(i + 1, n):
            if heights[i] > heights[j] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Longest bitonic subsequence length
    best = 0
    for i in range(n):
        # subtract 1 to avoid counting peak twice
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > best:
            best = bitonic_len

    return n - best

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is a sequence that strictly increases up to a peak and then strictly decreases.

    :param heights: List[int] - the heights of the students.
    :return: int - minimum number of students to remove.
    """
    # Validate input
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    for h in heights:
        if not isinstance(h, int):
            raise TypeError("heights must contain integers only")

    n = len(heights)
    if n <= 2:
        return 0

    # Longest increasing subsequence length ending at each index
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Longest decreasing subsequence length starting at each index
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1  # peak counted twice
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    # Minimum removals is the complement of the longest bitonic subsequence
    return n - max_bitonic

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
    heights (List[int]): A list of student heights.

    Returns:
    int: The minimum number of students that need to leave.
    """
    if not isinstance(heights, (list, tuple)):
        raise TypeError("heights must be a list or tuple of integers")
    n = len(heights)
    if n == 0:
        return 0

    # Compute longest strictly increasing subsequence lengths ending at each index
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Compute longest strictly decreasing subsequence lengths starting at each index
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[i] > heights[j] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Find maximum length of bitonic subsequence (increase then decrease)
    max_len = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1  # peak counted twice
        if bitonic_len > max_len:
            max_len = bitonic_len

    # Minimum deletions needed to achieve a mountain sequence
    return n - max_len

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
    student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
    list: A list of tuples sorted according to the above rules.
    """
    try:
        # Validate that input is a list of tuples with three elements each
        if not isinstance(student_scores, list):
            raise TypeError("student_scores must be a list")
        for item in student_scores:
            if not (isinstance(item, tuple) and len(item) == 3):
                raise TypeError("Each item in student_scores must be a tuple of (student_number, total_score, Chinese_score)")
            if not (isinstance(item[0], int) and isinstance(item[1], (int, float)) and isinstance(item[2], (int, float))):
                raise TypeError("student_number must be int; total_score and Chinese_score must be numeric")
        # Sort using the specified criteria
        return sorted(student_scores, key=lambda t: (-t[1], -t[2], t[0]))
    except Exception as e:
        raise ValueError(f"Invalid input encountered: {e}") from e
